using TomasAI.IFM.Shared.EventSourcing;
using TomasAI.IFM.Domain.Trade.Futures.Option.Trade.Command.State;using TomasAI.IFM.Domain.Trade.Shared.Futures.Option.Trade;using TomasAI.IFM.Domain.Trade.Shared.Model;using TomasAI.IFM.Domain.Trade.Shared.Trade;using TomasAI.IFM.Domain.Trade.Model;using TomasAI.IFM.Shared.Domain;
namespace TomasAI.IFM.Domain.Trade.Futures.Option.Trade.Command.Extensions;
public static class FuturesOptionTradeCommandHandlers{public static ServiceResult<GuidResult>Execute(this CreateOptionTradeCommand c,FuturesOptionTradeCommandState s)=>Apply(c,s,m=>m.Create(c.Trade));public static ServiceResult<GuidResult>Execute(this AmendOptionTradeEvidenceCommand c,FuturesOptionTradeCommandState s)=>Apply(c,s,m=>m.AmendEvidence(c.AmendmentId,c.CommissionDelta));public static ServiceResult<GuidResult>Execute(this BeginCloseOptionTradeCommand c,FuturesOptionTradeCommandState s)=>Apply(c,s,static m=>m.BeginClose());public static ServiceResult<GuidResult>Execute(this CloseOptionTradeCommand c,FuturesOptionTradeCommandState s)=>Apply(c,s,static m=>m.Close());static ServiceResult<GuidResult>Apply(EstablishedTradeCommand c,FuturesOptionTradeCommandState s,Func<EstablishedTradeActorStateMachine,TradeDecision<EstablishedTradeDefinition>>f){var initial=c is CreateOptionTradeCommand&&s.Current is null;var m=new EstablishedTradeActorStateMachine();if(s.Current is{}x)m.Replay(x);var d=f(m);if(!d.Accepted||d.Value is null)return TradeCommandResult.Rejected(c.ErrorCode,d);s.Update(new OptionTradeChangedEvent{EntityId=c.EntityId,State=d.Value,IsInitialEstablishment=initial},c);return TradeCommandResult.Accepted(c.CommandId);}}
